:root{
  --color-background-primary:#07111e;
  --color-background-secondary:#0d1b2e;
  --color-background-tertiary:#13253d;
  --color-background-info:#10264a;
  --color-background-danger:#3a1620;
  --color-background-success:#0f2f2a;
  --color-background-warning:#3a2d12;
  --color-text-primary:#f3f5fa;
  --color-text-secondary:#c6d0e3;
  --color-text-tertiary:#93a1bd;
  --color-text-info:#9db8ff;
  --color-text-danger:#ff9aa8;
  --color-text-success:#7fe0c3;
  --color-text-warning:#f0c674;
  --color-border-tertiary:#1e2f4d;
  --color-border-secondary:#2d456e;
  --color-border-primary:#3e5c8f;
  --accent:#7c9eff;
  --font-sans:-apple-system,BlinkMacSystemFont,"Hiragino Sans","Hiragino Kaku Gothic ProN","Yu Gothic","Noto Sans JP","Segoe UI",Roboto,sans-serif;
  --font-serif:"Hiragino Mincho ProN","Yu Mincho","Noto Serif JP",Georgia,serif;
  --font-mono:ui-monospace,SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;
  --border-radius-md:8px;
  --border-radius-lg:12px;
  --border-radius-xl:16px;
  --sidebar-w:320px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--color-background-primary);color:var(--color-text-primary);font-family:var(--font-sans);font-size:1rem;line-height:1.7;font-weight:400;overflow-wrap:anywhere}
a{color:var(--accent)}
strong,b{font-weight:500;color:var(--color-text-primary)}

/* ---------- sidebar ---------- */
.sidebar{position:fixed;top:0;left:0;bottom:0;width:var(--sidebar-w);overflow-y:auto;background:var(--color-background-secondary);border-right:1px solid var(--color-border-tertiary);padding:1.5rem 1rem 2rem;z-index:50}
.brand{display:block;padding:0 .75rem 1.25rem;margin-bottom:1rem;border-bottom:1px solid var(--color-border-tertiary);text-decoration:none}
.brand-name{display:block;color:var(--color-text-primary);font-weight:500;font-size:1.25rem;line-height:1.4}
.brand-sub{display:block;color:var(--color-text-tertiary);margin-top:.25rem}
.sidebar nav ul{list-style:none;margin:0;padding:0}
.sidebar nav li{padding-left:0;margin:.125rem 0}
.sidebar nav li::before{content:none}
.sidebar nav a{display:block;padding:.5rem .75rem;border-radius:var(--border-radius-md);border-left:2px solid transparent;color:var(--color-text-secondary);text-decoration:none;line-height:1.5}
.sidebar nav a:hover{background:var(--color-background-tertiary);color:var(--color-text-primary)}
.sidebar nav a.active{background:var(--color-background-info);color:var(--color-text-info);border-left-color:var(--accent)}

/* ---------- layout ---------- */
.layout{display:block}
.main{margin-left:var(--sidebar-w);padding:2rem 3rem 4rem}

/* ---------- hero ---------- */
.hero{padding:1.5rem 0 2rem;border-bottom:1px solid var(--color-border-tertiary)}
.eyebrow{display:inline-flex;align-items:center;gap:.5rem;color:var(--color-text-info);font-weight:500}
.hero h1{font-size:2.25rem;font-weight:500;line-height:1.3;margin:.5rem 0 .75rem;color:var(--color-text-primary)}
.hero .sub{color:var(--color-text-secondary);font-size:1.25rem;margin:0 0 1.75rem;line-height:1.6}
.meta{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem;margin:0}
.meta-item{padding:1rem 1.25rem;background:var(--color-background-secondary);border:1px solid var(--color-border-tertiary);border-radius:var(--border-radius-lg)}
.meta-item dt{color:var(--color-text-info);font-weight:500;margin:0 0 .25rem}
.meta-item dd{margin:0;color:var(--color-text-secondary)}

/* ---------- sections ---------- */
.section{padding:2.5rem 0 1rem;border-top:1px solid var(--color-border-tertiary);scroll-margin-top:1rem}
.hero + .section{border-top:none}
.section>h2{font-size:1.6rem;font-weight:500;line-height:1.4;margin:0 0 1.25rem;padding-left:1rem;border-left:4px solid var(--accent);color:var(--color-text-primary)}
.prose h3{font-size:1.25rem;font-weight:500;line-height:1.5;margin:2.25rem 0 .75rem;color:var(--color-text-info)}
.prose h4{font-size:1rem;font-weight:500;margin:1.5rem 0 .5rem;color:var(--color-text-primary)}
.prose p{margin:.9rem 0;color:var(--color-text-secondary)}
.prose p strong{color:var(--color-text-primary)}
.prose a{color:var(--accent);text-underline-offset:3px}

.prose ul{list-style:none;margin:1rem 0;padding:0}
.prose ul>li{position:relative;display:block;padding-left:1.5rem;margin:.5rem 0;color:var(--color-text-secondary)}
.prose ul>li::before{content:"";position:absolute;left:.25rem;top:.78em;width:.5rem;height:.5rem;border-radius:50%;background:var(--accent)}
.prose ol{list-style:none;margin:1rem 0;padding:0;counter-reset:n}
.prose ol>li{position:relative;display:block;padding-left:2.5rem;margin:.65rem 0;counter-increment:n;color:var(--color-text-secondary)}
.prose ol>li::before{content:counter(n);position:absolute;left:0;top:.1rem;width:1.75rem;height:1.75rem;border-radius:50%;background:var(--color-background-info);border:1px solid var(--color-border-primary);color:var(--color-text-info);font-weight:500;text-align:center;line-height:1.65rem}

/* ---------- inline code ---------- */
code{font-family:var(--font-mono);font-size:1rem;background:var(--color-background-tertiary);border:1px solid var(--color-border-tertiary);border-radius:6px;padding:.05rem .4rem;color:var(--color-text-info);overflow-wrap:anywhere}

/* ---------- tables ---------- */
.table-wrap{overflow-x:auto;margin:1.25rem 0;border:1px solid var(--color-border-secondary);border-radius:var(--border-radius-lg)}
table{border-collapse:collapse;width:100%;min-width:560px;font-size:1rem}
th,td{padding:.75rem 1rem;text-align:left;vertical-align:top;line-height:1.6;border-bottom:1px solid var(--color-border-tertiary);color:var(--color-text-secondary);overflow-wrap:anywhere}
th{background:var(--color-background-tertiary);color:var(--color-text-primary);font-weight:500;white-space:nowrap}
td strong{color:var(--color-text-primary)}
tbody tr:last-child td{border-bottom:none}
tbody tr:nth-child(even) td{background:var(--color-background-secondary)}

/* ---------- callouts ---------- */
.callout{position:relative;margin:1.25rem 0;padding:1rem 1.25rem 1rem 3.5rem;border:1px solid var(--color-border-secondary);border-left:3px solid var(--accent);border-radius:var(--border-radius-lg);background:var(--color-background-info)}
.callout>i.ti{position:absolute;left:1.1rem;top:1rem;font-size:1.5rem;line-height:1.4;color:var(--color-text-info)}
.callout p{margin:.5rem 0;color:var(--color-text-primary)}
.callout p:first-of-type{margin-top:0}
.callout p:last-of-type{margin-bottom:0}
.callout.tip{background:var(--color-background-success);border-color:var(--color-border-secondary);border-left-color:var(--color-text-success)}
.callout.tip>i.ti{color:var(--color-text-success)}
.callout.warn{background:var(--color-background-warning);border-left-color:var(--color-text-warning)}
.callout.warn>i.ti{color:var(--color-text-warning)}
.callout code{background:var(--color-background-primary)}

/* ---------- code ---------- */
.code-block{margin:1.25rem 0;border:1px solid var(--color-border-secondary);border-radius:var(--border-radius-lg);overflow:hidden;background:#0a1626}
.code-head{padding:.5rem 1rem;background:var(--color-background-tertiary);border-bottom:1px solid var(--color-border-tertiary);color:var(--color-text-tertiary);font-family:var(--font-mono);text-transform:lowercase}
.code-block pre{margin:0;padding:1rem 1.25rem;overflow-x:auto;background:transparent}
.code-block pre code,pre code.hljs{display:block;background:transparent;border:0;padding:0;border-radius:0;font-family:var(--font-mono);font-size:1rem;line-height:1.65;white-space:pre;overflow-wrap:normal;color:var(--color-text-primary)}

/* ---------- diagrams ---------- */
.diagram{margin:1.5rem 0;padding:1.5rem 1rem;background:var(--color-background-secondary);border:1px solid var(--color-border-secondary);border-radius:var(--border-radius-lg);overflow-x:auto}
.mermaid-target{display:flex;justify-content:center;min-height:3rem;color:var(--color-text-tertiary)}
.mermaid-target svg{max-width:100%;height:auto;overflow:visible}
.diagram-error{color:var(--color-text-danger)}

/* ---------- references ---------- */
.ref-list{display:grid;gap:.75rem;margin:1rem 0 1.5rem}
.ref-card{display:grid;grid-template-columns:2.5rem 1fr;gap:1rem;padding:1rem 1.25rem;background:var(--color-background-secondary);border:1px solid var(--color-border-secondary);border-radius:var(--border-radius-lg)}
.ref-badge{display:flex;align-items:center;justify-content:center;width:2.25rem;height:2.25rem;border-radius:50%;background:var(--color-background-info);border:1px solid var(--color-border-primary);color:var(--color-text-info);font-weight:500}
.ref-tag{display:inline-block;padding:.1rem .6rem;border-radius:999px;background:var(--color-background-tertiary);border:1px solid var(--color-border-secondary);color:var(--color-text-info);font-weight:500}
.ref-desc{margin:.5rem 0 .5rem;color:var(--color-text-primary)}
.ref-url{display:inline-flex;align-items:flex-start;gap:.4rem;color:var(--accent);text-decoration:none;font-family:var(--font-mono);overflow-wrap:anywhere;word-break:break-all}
.ref-url:hover{text-decoration:underline}
.ref-url span{min-width:0}

/* ---------- footer ---------- */
.footer{margin-top:3rem;padding:1.5rem 0 0;border-top:1px solid var(--color-border-tertiary);color:var(--color-text-tertiary)}
.footer p{margin:.25rem 0}

/* ---------- mobile / tablet drawer ---------- */
.burger{display:none;position:fixed;right:1.25rem;bottom:1.25rem;width:3.5rem;height:3.5rem;padding:0;border-radius:50%;border:1px solid var(--color-border-primary);background:var(--color-background-info);color:var(--color-text-info);cursor:pointer;z-index:60;align-items:center;justify-content:center}
.burger svg{width:1.5rem;height:1.5rem}
.burger .ic-close{display:none}
body.nav-open .burger .ic-open{display:none}
body.nav-open .burger .ic-close{display:block}
.backdrop{display:none}
@media (max-width:1024px){
  .sidebar{width:min(320px,86vw);transform:translateX(-100%);transition:transform .25s ease}
  body.nav-open .sidebar{transform:translateX(0)}
  .backdrop{display:block;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(3,8,15,.72);opacity:0;pointer-events:none;transition:opacity .25s ease;z-index:40}
  body.nav-open .backdrop{opacity:1;pointer-events:auto}
  body.nav-open{overflow:hidden}
  .burger{display:flex}
  .main{margin-left:0;padding:1.25rem 1.25rem 5.5rem}
  .hero h1{font-size:1.75rem}
  .hero .sub{font-size:1.1rem}
}
@media (max-width:600px){
  .main{padding:1rem 1rem 5.5rem}
  .section>h2{font-size:1.35rem}
  .callout{padding-left:3.25rem}
  .ref-card{grid-template-columns:1fr}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  .sidebar,.backdrop{transition:none}
}
